/* Gruvbox, like vimium-settings.json. Vimium C's own names: .LH is one hint
   marker, .MC a typed character in it, .HUD the bottom bar. */
/* -------- HINTS -------- */
.LH, .D>.LH, .HM>.LH {
  background: #282828 !important;
  border: 1px solid #DCDCCC !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 3px 4px;
  color: #d8a657 !important;
  font-family: "Cascadia Code NF", monospace;
  font-size: 13px;
  font-weight: normal;
  text-shadow: none;
}
.LH > .MC { color: #d8a657 !important; opacity: 0.3; }
.LH > .MC ~ span { color: #89b482 !important; }

/* -------- HUD -------- */
.HUD, .HUD.D { color: #d4be98 !important; font-family: "Cascadia Code NF", monospace; font-size: 13px; }
.HUD:after, .HUD.D:after { background: #282828 !important; border: 1px solid #3c3836 !important; border-radius: 0 !important; }
